<?php
require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$id=(int)$_SESSION['id'];$target=trim((string)($_GET['user']??$_POST['user']??''));$notice='';$s=tt_prepare($db,'SELECT `friends` FROM `accounts` WHERE `id`=?');$s->bind_param('i',$id);$s->execute();$s->bind_result($raw);$s->fetch();$s->close();$friends=array_values(array_unique(array_filter(preg_split('/[;\r\n]+/',(string)$raw)?:[])));if($_SERVER['REQUEST_METHOD']==='POST'&&$target!==''){$action=(string)($_POST['action']??'add');if($target===($_SESSION['name']??'')){$notice='You cannot friend yourself.';}else{$check=tt_prepare($db,'SELECT `id` FROM `accounts` WHERE `username`=? LIMIT 1');$check->bind_param('s',$target);$check->execute();$check->store_result();$exists=$check->num_rows===1;$check->close();if(!$exists){$notice='User not found.';}else{if($action==='remove')$friends=array_values(array_filter($friends,fn($x)=>$x!==$target));elseif(!in_array($target,$friends,true))$friends[]=$target;$raw=implode(';',$friends);$u=tt_prepare($db,'UPDATE `accounts` SET `friends`=? WHERE `id`=?');$u->bind_param('si',$raw,$id);$u->execute();$u->close();$_SESSION['friends']=$raw;$notice=$action==='remove'?'Friend removed.':'Friend added.';}}}$db->close();
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Friends</title></head><body><?php tt_nav('profile.php');?><main class="content"><h2>Friends</h2><?php if($notice):?><p class="notice"><?=tt_h($notice)?></p><?php endif;?><?php if($target!==''):?><form method="post"><input type="hidden" name="user" value="<?=tt_h($target)?>"><p>Manage <?=tt_h($target)?></p><button name="action" value="add">Add</button> <button name="action" value="remove">Remove</button></form><?php endif;?><section class="card"><?php foreach($friends as $f):?><p><a href="profile.php?user=<?=urlencode($f)?>"><?=tt_h($f)?></a></p><?php endforeach;?><?php if(!$friends):?><p>No friends saved yet.</p><?php endif;?></section></main></body></html>